  const getOneFile = () => {
    axios
      .get(`/api/upload/${"5ec74bfa312ab08288522a01"}`)
      .then(res => {
        parseStepFile(res.data);
        //display3DFile();   this function is an example of how to send stuff from components backwards
      })
